function closeCalls(readings, tolerance) {
  let pairs = 0;
  for (let i = 0; i < readings.length; i++) {
    for (let j = i + 1; j < readings.length; j++) {
      if (Math.abs(readings[i] - readings[j]) <= tolerance) pairs++;
    }
  }
  return pairs;
}

function closeCalls(readings, tolerance) {
  const sorted = Int32Array.from(readings).sort();
  let low = 0;
  let pairs = 0;
  for (let high = 0; high < sorted.length; high++) {
    while (sorted[high] - sorted[low] > tolerance) low++;
    pairs += high - low;
  }
  return pairs;
}
